var LOGIN_REWARDS=[50,60,70,80,100,120,300];
function checkDailyLogin(){var today=dateKey();if(profile.lastLoginDate===today)return;var streak=(profile.lastLoginDate===yesterdayKey())?(profile.loginStreak||0)+1:1;var idx=(streak-1)%7,chips=LOGIN_REWARDS[idx],sp=idx===6?1:0;profile.loginStreak=streak;profile.lastLoginDate=today;profile.chips+=chips;profile.skillPoints+=sp;scheduleSaveProfile();showDailyPopup(streak,idx,chips,sp)}
function showDailyPopup(streak,idx,chips,sp){var cells='';for(var i=0;i<7;i++){cells+='<div class="dl-cell'+(i<idx?' done':(i===idx?' today':''))+'"><b>Ngày '+(i+1)+'</b><span>'+(i===6?'🎁':'💎')+'</span><small>'+LOGIN_REWARDS[i]+(i===6?' +1SP':'')+'</small></div>'}$('dailyBody').innerHTML='<h2>🔥 ĐIỂM DANH</h2><div class="dl-streak">Chuỗi '+streak+' ngày</div><div class="dl-grid">'+cells+'</div><div class="dl-got">+'+chips+' 💎'+(sp?' · +'+sp+' 🔮 SP':'')+'</div><div class="dl-note">Bỏ lỡ 1 ngày mất chuỗi!</div><button class="btn btn-primary btn-lg" id="dailyOkBtn">Nhận</button>';$('dailyOkBtn').onclick=function(){$('dailyOverlay').hidden=true;renderMenuExtras()};$('dailyOverlay').hidden=false;sfx.win()}
var QUEST_DEFS={play:{name:'Chơi 2 ván',target:2,chips:40,xp:30},win:{name:'Thắng 1 ván',target:1,chips:80,xp:60},buy:{name:'Mua 4 ô',target:4,chips:40,xp:30},upgrade:{name:'Nâng cấp 2 lần',target:2,chips:40,xp:30},rent:{name:'Thu thuê 3 lần',target:3,chips:50,xp:40},rich:{name:'Kết thúc ≥ $300k',target:1,chips:60,xp:40},chain:{name:'Chuỗi ≥ 3 ô',target:1,chips:60,xp:40}};
function ensureQuests(){var today=dateKey();if(profile.quests.date===today&&profile.quests.list.length)return;var ids=seededShuffle(Object.keys(QUEST_DEFS),today+'|'+myUsername).slice(0,3);profile.quests={date:today,bonus:false,list:ids.map(function(id){return{id:id,prog:0,claimed:false}})};scheduleSaveProfile()}
function questAdd(id,n){ensureQuests();var q=profile.quests.list.find(function(x){return x.id===id});if(!q)return;var def=QUEST_DEFS[id];if(q.prog>=def.target)return;q.prog=Math.min(def.target,q.prog+(n||1));if(q.prog>=def.target)toast('📋 Xong: '+def.name);scheduleSaveProfile()}
function countClaimable(){ensureQuests();return profile.quests.list.filter(function(q){return!q.claimed&&q.prog>=QUEST_DEFS[q.id].target}).length}
function claimQuest(i){ensureQuests();var q=profile.quests.list[i];if(!q)return;var def=QUEST_DEFS[q.id];if(q.claimed||q.prog<def.target)return;q.claimed=true;profile.chips+=def.chips;addXP(def.xp);sfx.buy();toast('🎁 +'+def.chips+'💎 +'+def.xp+' XP');if(!profile.quests.bonus&&profile.quests.list.every(function(x){return x.claimed})){profile.quests.bonus=true;var r=openChest(true);setTimeout(function(){toast(r.label+': '+r.text);sfx.event()},1300)}scheduleSaveProfile();renderQuests();renderMenuExtras()}
function openChest(boost){var roll=Math.random()*100;var jack=boost?5:2,epic=boost?20:10,rare=boost?45:30;var res,c;if(roll<jack){profile.chips+=500;profile.skillPoints+=1;res={tier:'jackpot',label:'💥 JACKPOT',text:'+500 💎 +1 🔮 SP'}}else if(roll<jack+epic){var pool=[],id;for(id in DICE_SKINS)if(DICE_SKINS[id].cost>0&&DICE_SKINS[id].cost<=1000&&profile.ownedDice.indexOf(id)<0)pool.push({k:'dice',id:id});for(id in BOARD_SKINS)if(BOARD_SKINS[id].cost>0&&BOARD_SKINS[id].cost<=1000&&profile.ownedBoards.indexOf(id)<0)pool.push({k:'board',id:id});if(pool.length){var pk=pool[rnd(pool.length)];if(pk.k==='dice'){profile.ownedDice.push(pk.id);res={tier:'epic',label:'🌟 Rương Sử Thi',text:'Mở '+DICE_SKINS[pk.id].name}}else{profile.ownedBoards.push(pk.id);res={tier:'epic',label:'🌟 Rương Sử Thi',text:'Mở bàn '+BOARD_SKINS[pk.id].name}}}else{var bk=Object.keys(BOOSTERS),bid=bk[rnd(bk.length)];profile.ownedBoosters[bid]=(profile.ownedBoosters[bid]||0)+1;res={tier:'epic',label:'🌟 Rương Sử Thi',text:'+1 '+BOOSTERS[bid].name}}}else if(roll<jack+epic+rare){c=80+rnd(71);profile.chips+=c;res={tier:'rare',label:'💠 Rương Hiếm',text:'+'+c+' 💎'}}else{c=20+rnd(41);profile.chips+=c;res={tier:'common',label:'📦 Rương Thường',text:'+'+c+' 💎'}}scheduleSaveProfile();return res}
var ACH_LIST=[{id:'first_win',name:'Thắng đầu tiên',icon:'🏆',chips:50,target:1,get:function(p){return p.stats.wins}},{id:'win10',name:'Thắng 10 ván',icon:'👑',chips:200,target:10,get:function(p){return p.stats.wins}},{id:'play20',name:'Chơi 20 ván',icon:'🎮',chips:100,target:20,get:function(p){return p.stats.plays}},{id:'buy50',name:'Mua 50 ô',icon:'🏠',chips:100,target:50,get:function(p){return p.stats.buys}},{id:'up20',name:'Nâng cấp 20 lần',icon:'🏗️',chips:100,target:20,get:function(p){return p.stats.upgrades}},{id:'lv5',name:'Đạt Lv.5',icon:'⭐',chips:50,sp:1,target:5,get:function(p){return p.level}},{id:'streak7',name:'Điểm danh 7 ngày',icon:'🔥',chips:150,target:7,get:function(p){return p.loginStreak}},{id:'collect',name:'Sưu tập 6 skin',icon:'🎨',chips:150,target:6,get:function(p){return p.ownedDice.length+p.ownedBoards.length}},{id:'skill3',name:'Mở 3 kỹ năng',icon:'🌳',chips:100,target:3,get:function(p){return Object.keys(p.skills).length}}];
var achBusy=false;
function checkAchievements(){if(achBusy||!profile||!profile.stats)return;achBusy=true;try{ACH_LIST.forEach(function(a){if(profile.achievements[a.id])return;if(a.get(profile)>=a.target){profile.achievements[a.id]=true;profile.chips+=a.chips;if(a.sp)profile.skillPoints+=a.sp;setTimeout(function(){toast('🏅 '+a.name);sfx.event()},1500)}})}finally{achBusy=false}}
function renderMenuExtras(){var s=$('menuStreak');if(s){var parts=[];if(profile.loginStreak>0)parts.push('🔥 Chuỗi '+profile.loginStreak+' ngày');if(isWeekend())parts.push('⚡ Cuối tuần x2 XP');s.textContent=parts.join(' · ')}var qb=$('gotoQuestsBtn');if(qb){var n=countClaimable();qb.innerHTML='📋 Nhiệm Vụ'+(n?'<span class="badge">'+n+'</span>':'')}}
function renderQuests(){ensureQuests();var now=new Date(),end=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1);$('questTimer').textContent='Làm mới sau ~'+Math.ceil((end-now)/36e5)+' giờ';var box=$('questList'),html='';profile.quests.list.forEach(function(q,i){var d=QUEST_DEFS[q.id],done=q.prog>=d.target;var right=q.claimed?'<span style="font-size:11px;color:#00ff66;font-weight:800">✓ Đã nhận</span>':(done?'<button class="btn btn-primary btn-sm" data-claim="'+i+'">Nhận</button>':'<span style="font-size:12px;font-weight:800;color:#a0aabf">'+q.prog+'/'+d.target+'</span>');html+='<div class="q-item'+(q.claimed?' claimed':(done?' done':''))+'"><div class="q-info"><div class="q-name">'+esc(d.name)+'</div><div class="q-rw">💎 '+d.chips+' · ⭐ '+d.xp+' XP</div><div class="q-bar"><i style="width:'+Math.min(100,q.prog/d.target*100)+'%"></i></div></div>'+right+'</div>'});html+='<div class="q-sub">'+(profile.quests.bonus?'🎁 Đã nhận Rương Bonus':'Xong cả 3 → mở Rương Bonus 🎁')+'</div>';box.innerHTML=html;var ah='';ACH_LIST.forEach(function(a){var ok=!!profile.achievements[a.id],cur=Math.min(a.get(profile),a.target);ah+='<div class="a-item '+(ok?'unlocked':'locked')+'"><div class="a-ico">'+a.icon+'</div><div class="q-info"><div class="q-name">'+esc(a.name)+'</div><div class="q-rw">'+(ok?'✓ Đã mở':cur+'/'+a.target)+' · 💎 '+a.chips+(a.sp?' · 🔮 '+a.sp:'')+'</div></div></div>'});$('achList').innerHTML=ah}
async function renderLeaderboard(){var box=$('lbList');ensureWeek();$('lbSub').textContent='Tuần này bạn thắng '+profile.weekWins+' ván · reset thứ Hai';if(!sb||!syncOnline){box.innerHTML='<div class="q-sub">Cần kết nối server</div>';return}box.innerHTML='<div class="q-sub">Đang tải...</div>';try{await flushSaveProfile();var r=await sb.from('monopoly_profiles').select('username,display_name,week_wins,level').eq('week_key',weekKey()).gt('week_wins',0).order('week_wins',{ascending:false}).limit(10);if(r.error)throw r.error;if(!r.data||!r.data.length){box.innerHTML='<div class="q-sub">Chưa ai thắng tuần này</div>';return}var medals=['🥇','🥈','🥉'],html='';r.data.forEach(function(row,i){html+='<div class="lb-row'+(row.username===myUsername?' me':'')+'"><div class="lb-rank">'+(medals[i]||'#'+(i+1))+'</div><div class="lb-name">'+esc(row.display_name||row.username)+' <small style="color:#a0aabf">Lv.'+(row.level||1)+'</small></div><div class="lb-wins">'+row.week_wins+' 🏆</div></div>'});box.innerHTML=html}catch(e){box.innerHTML='<div class="q-sub">Không tải được BXH</div>'}}
function buildHints(){var lines=[];lines.push('⭐ Còn '+(xpForLevel(profile.level)-profile.xp)+' XP lên Lv.'+(profile.level+1));var best=null;function scan(map,owned){for(var id in map)if(owned.indexOf(id)<0&&(!best||map[id].cost<best.cost))best={name:map[id].name,cost:map[id].cost}}scan(DICE_SKINS,profile.ownedDice);scan(BOARD_SKINS,profile.ownedBoards);if(best){var need=best.cost-profile.chips;lines.push(need>0?'💎 Còn '+need+' Chips mua '+best.name:'🛒 Đủ Chips mua '+best.name)}var claim=countClaimable();if(claim)lines.push('📋 '+claim+' nhiệm vụ chờ nhận');return lines.join('<br>')}
var state={playMode:'bot',botCount:1,game:null,busy:false,animating:false,selectedBooster:null};
var myUsername='',myDisplayName='',myProfile=null;
var room=null,roomPlayers=[];
var roomChan=null,roomsChan=null,pollTimer=null,isHost=false,debugOpen=false,dbgEvents=[];
