function dbgEvent(type,detail){dbgEvents.push({time:new Date(),type:type,detail:detail||''});if(dbgEvents.length>60)dbgEvents.shift();if(window.console)console.log('[MP]',type,detail||'');if(debugOpen)renderDbg()}
function getMyUsername(){try{if(window.SRank&&window.SRank.Auth&&typeof window.SRank.Auth.getCurrentUser==='function'){var uObj=window.SRank.Auth.getCurrentUser();if(uObj){myDisplayName=uObj.displayName||uObj.username||'';return uObj.username||myDisplayName}}}catch(e){}var u='';try{var keys=['srank_username','username'];for(var i=0;i<keys.length;i++){var v=localStorage.getItem(keys[i]);if(v){try{u=JSON.parse(v).username||v}catch(_){u=v}if(u)break}}if(!u&&window.SRANK_STATE&&window.SRANK_STATE.currentUser)u=window.SRANK_STATE.currentUser.username}catch(e){}if(!u){u=localStorage.getItem('srank_guest_id');if(!u){u='guest_'+rnd(99999);localStorage.setItem('srank_guest_id',u)}}myDisplayName=u;return String(u).trim()}
var actx=null,sfxOn=true;
function beep(f,d,t,v){if(!sfxOn)return;try{if(!actx)actx=new(window.AudioContext||window.webkitAudioContext)();var t0=actx.currentTime,o=actx.createOscillator(),g=actx.createGain();o.type=t||'sine';o.frequency.setValueAtTime(f,t0);g.gain.setValueAtTime(.0001,t0);g.gain.exponentialRampToValueAtTime(v||.04,t0+.01);g.gain.exponentialRampToValueAtTime(.0001,t0+d);o.connect(g);g.connect(actx.destination);o.start(t0);o.stop(t0+d+.05)}catch(e){}}
var sfx={roll:function(){for(var i=0;i<6;i++)setTimeout(function(){beep(400+rnd(400),.05,'square',.03)},i*50)},step:function(){beep(800+rnd(200),.05,'sine',.02)},land:function(){beep(600,.1,'sine',.04)},buy:function(){[659,880,1046].forEach(function(f,i){setTimeout(function(){beep(f,.1,'triangle',.05)},i*70)})},pay:function(){[300,250,200].forEach(function(f,i){setTimeout(function(){beep(f,.15,'sawtooth',.04)},i*70)})},win:function(){[523,659,784,1046,1318,1567].forEach(function(f,i){setTimeout(function(){beep(f,.15,'square',.05)},i*80)})},lose:function(){[400,300,200,100].forEach(function(f,i){setTimeout(function(){beep(f,.2,'sawtooth',.05)},i*100)})},event:function(){[880,1108,1318,1760].forEach(function(f,i){setTimeout(function(){beep(f,.2,'square',.06)},i*100)})}};
function fitBoard(){var board=$('board');if(!board)return;var w=board.clientWidth,h=board.clientHeight;var tileW=(w-36)/8,tileH=(h-50)/8;board.style.setProperty('--tile-size',Math.min(tileW,tileH)+'px')}
function showTurnBanner(name,color){var b=$('turnBanner');if(!b)return;b.textContent='👉 '+name;b.style.color=color||'#00f0ff';b.classList.remove('show');void b.offsetWidth;b.classList.add('show');clearTimeout(b._t);b._t=setTimeout(function(){b.classList.remove('show')},1600)}
function showMoneyFloat(username,amount){var pawn=shadow.querySelector('.pawn-box[data-user="'+username+'"]');var rect=pawn?pawn.getBoundingClientRect():{left:innerWidth/2,right:innerWidth/2,top:innerHeight/2,width:0};var f=document.createElement('div');f.className='money-float';f.textContent=(amount>0?'+':'−')+'$'+Math.abs(amount).toLocaleString();f.style.left=(rect.left+rect.width/2)+'px';f.style.top=(rect.top)+'px';f.style.color=amount>0?'#00ff66':'#ff2a75';shadow.appendChild(f);setTimeout(function(){try{f.remove()}catch(e){}},1500)}
function spawnConfetti(count){var colors=['#00f0ff','#ff2a75','#00ff66','#ffcc00','#b000ff','#ffffff'];for(var i=0;i<count;i++){var c=document.createElement('div');c.className='confetti';c.style.left=(Math.random()*100)+'%';c.style.background=colors[rnd(colors.length)];c.style.width=(6+Math.random()*8)+'px';c.style.height=(6+Math.random()*10)+'px';c.style.animationDelay=(Math.random()*0.8)+'s';c.style.animationDuration=(2+Math.random()*2.5)+'s';if(Math.random()>0.6)c.style.borderRadius='50%';shadow.appendChild(c);(function(el){setTimeout(function(){try{el.remove()}catch(e){}},5500)})(c)}}
function getChainCount(tileIdx){var tile=state.game.tiles[tileIdx];if(tile.type!=='prop'||!tile.owner)return 0;var owner=tile.owner,zone=tile.zone,range=ZONE_RANGES[zone],count=1;for(var i=tileIdx-1;i>=range.start;i--){if(state.game.tiles[i].owner===owner)count++;else break}for(var i=tileIdx+1;i<=range.end;i++){if(state.game.tiles[i].owner===owner)count++;else break}return count}
function getBaseValue(tileIdx){var tile=state.game.tiles[tileIdx];if(tile.type!=='prop'||!tile.owner)return ZONES[tile.zone].price;return ZONES[tile.zone].price*getChainCount(tileIdx)}
function weightedRoll(weights){var total=0;for(var k in weights)total+=weights[k];var r=Math.random()*total;for(var k in weights){r-=weights[k];if(r<=0)return parseInt(k)}return 6}
function rollDiceForPlayer(player){var weights={1:1,2:1,3:1,4:1,5:1,6:1};var skin=(player.username===myUsername)?profile.activeDice:'silver';if(skin==='gold')weights[6]=1.2;if(skin==='neon'&&player.money<100000){weights[1]=1.3;weights[2]=1.3;weights[3]=1.3}if(skin==='matrix'&&lastDiceRoll>0&&Math.random()<0.15)return lastDiceRoll;if(consecutiveLowRolls>=3){weights[5]*=2;weights[6]*=2}var roll=weightedRoll(weights);if(roll<=2)consecutiveLowRolls++;else consecutiveLowRolls=0;lastDiceRoll=roll;return roll}
function renderProfile(){$('profileAvatar').src=avt(myUsername);$('profileName').textContent=myDisplayName||myUsername;$('profileLevel').textContent=profile.level;var pct=Math.min(100,(profile.xp/xpForLevel(profile.level))*100);$('xpFill').style.width=pct+'%';$('xpText').textContent=profile.xp+'/'+xpForLevel(profile.level)+' XP';$('statWins').textContent=profile.stats.wins;$('statPlays').textContent=profile.stats.plays;$('statChips').textContent=profile.chips;$('statSP').textContent=profile.skillPoints}
var currentShopTab='dice';
function renderShop(){$('shopChips').textContent=profile.chips;var content=$('shopContent');content.innerHTML='';if(currentShopTab==='dice'){for(var id in DICE_SKINS){var d=DICE_SKINS[id];var owned=profile.ownedDice.indexOf(id)>=0;var active=profile.activeDice===id;var canBuy=profile.chips>=d.cost;var btnClass=active?'equipped':(owned?'equip':'');var btnText=active?'✓ Đang Dùng':(owned?'Trang Bị':(d.cost+'💎'));var disabled=!owned&&!canBuy;content.innerHTML+='<div class="shop-item'+(active?' active-item':(owned?' owned':''))+'"><div class="shop-item-icon">'+d.icon+'</div><div class="shop-item-info"><div class="shop-item-name">'+d.name+'</div><div class="shop-item-desc">'+d.desc+'</div></div><button class="shop-item-btn '+btnClass+'" data-buydice="'+id+'" '+(active||disabled?'disabled':'')+'>'+btnText+'</button></div>'}}else if(currentShopTab==='boards'){for(var id in BOARD_SKINS){var b=BOARD_SKINS[id];var owned=profile.ownedBoards.indexOf(id)>=0;var active=profile.activeBoard===id;var canBuy=profile.chips>=b.cost;var btnClass=active?'equipped':(owned?'equip':'');var btnText=active?'✓ Đang Dùng':(owned?'Trang Bị':(b.cost+'💎'));var disabled=!owned&&!canBuy;content.innerHTML+='<div class="shop-item'+(active?' active-item':(owned?' owned':''))+'"><div class="shop-item-icon">'+b.icon+'</div><div class="shop-item-info"><div class="shop-item-name">'+b.name+'</div><div class="shop-item-desc">'+b.desc+'</div></div><button class="shop-item-btn '+btnClass+'" data-buyboard="'+id+'" '+(active||disabled?'disabled':'')+'>'+btnText+'</button></div>'}}else if(currentShopTab==='boosters'){for(var id in BOOSTERS){var bb=BOOSTERS[id];var cnt=profile.ownedBoosters[id]||0;var canBuy=profile.chips>=bb.cost;content.innerHTML+='<div class="shop-item"><div class="shop-item-icon">'+bb.icon+'</div><div class="shop-item-info"><div class="shop-item-name">'+bb.name+' ×'+cnt+'</div><div class="shop-item-desc">'+bb.desc+'</div></div><button class="shop-item-btn" data-buybooster="'+id+'" '+(canBuy?'':'disabled')+'>'+bb.cost+'💎</button></div>'}}}
function handleShopClick(e){var btn=e.target.closest('button');if(!btn)return;if(btn.dataset.buydice){var id=btn.dataset.buydice;var d=DICE_SKINS[id];if(profile.ownedDice.indexOf(id)<0){if(profile.chips<d.cost)return toast('Không đủ Chips!');profile.chips-=d.cost;profile.ownedDice.push(id)}profile.activeDice=id;scheduleSaveProfile();renderShop();sfx.buy();toast('Đã trang bị '+d.name)}else if(btn.dataset.buyboard){var id=btn.dataset.buyboard;var b=BOARD_SKINS[id];if(profile.ownedBoards.indexOf(id)<0){if(profile.chips<b.cost)return toast('Không đủ Chips!');profile.chips-=b.cost;profile.ownedBoards.push(id)}profile.activeBoard=id;scheduleSaveProfile();renderShop();sfx.buy();toast('Đã chọn bàn '+b.name)}else if(btn.dataset.buybooster){var id=btn.dataset.buybooster;var bb=BOOSTERS[id];if(profile.chips<bb.cost)return toast('Không đủ Chips!');profile.chips-=bb.cost;profile.ownedBoosters[id]=(profile.ownedBoosters[id]||0)+1;scheduleSaveProfile();renderShop();sfx.buy();toast('Đã mua '+bb.name)}}
function renderSkills(){$('skillSP').textContent=profile.skillPoints;['merchant','warrior','mage'].forEach(function(branch){var container=shadow.querySelector('#branch'+branch.charAt(0).toUpperCase()+branch.slice(1)+' .skill-list');container.innerHTML='';for(var id in SKILL_DEFS){var sk=SKILL_DEFS[id];if(sk.branch!==branch)continue;var unlocked=hasSkill(id);var reqMet=!sk.req||hasSkill(sk.req);var canLearn=!unlocked&&reqMet&&profile.skillPoints>=sk.cost;var cls='skill-node'+(unlocked?' unlocked':(canLearn?' can-learn':' locked'));container.innerHTML+='<div class="'+cls+'" data-skill="'+id+'"><div class="sn-icon">'+sk.icon+'</div><div class="sn-name">'+sk.name+'</div><div class="sn-desc">'+sk.desc+'</div><div class="sn-cost">'+(unlocked?'✓ ĐÃ MỞ':'🔮 '+sk.cost+' SP')+'</div></div>'}})}
function handleSkillClick(e){var node=e.target.closest('.skill-node');if(!node)return;var id=node.dataset.skill;if(!id||hasSkill(id))return;var sk=SKILL_DEFS[id];if(sk.req&&!hasSkill(sk.req))return toast('Cần mở '+SKILL_DEFS[sk.req].name);if(profile.skillPoints<sk.cost)return toast('Không đủ SP!');profile.skillPoints-=sk.cost;profile.skills[id]=true;scheduleSaveProfile();renderSkills();sfx.buy();toast('Đã mở khóa: '+sk.name)}
function renderBoosterSelect(){var container=$('boosterSelect');container.innerHTML='';var any=false;for(var id in profile.ownedBoosters){if((profile.ownedBoosters[id]||0)>0){any=true;var bb=BOOSTERS[id];var active=state.selectedBooster===id;container.innerHTML+='<div class="booster-card'+(active?' active':'')+'" data-booster="'+id+'"><div class="bc-icon">'+bb.icon+'</div><div class="bc-name">'+bb.name+' ×'+profile.ownedBoosters[id]+'</div><div class="bc-desc">'+bb.desc+'</div></div>'}}if(!any)container.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:14px;color:#888;font-size:12px;font-weight:700">Chưa có Booster. Mua trong Shop!</div>';container.onclick=function(e){var card=e.target.closest('.booster-card');if(!card)return;var id=card.dataset.booster;if(!id)return;state.selectedBooster=(state.selectedBooster===id)?null:id;renderBoosterSelect()}}
function initTiles(){var tiles=[];for(var i=0;i<28;i++){if(i===0)tiles.push({type:'start'});else if(i===7)tiles.push({type:'jail'});else if(i===14)tiles.push({type:'reward'});else if(i===21)tiles.push({type:'teleport'});else{var zone=0;for(var z=0;z<4;z++)if(i>=ZONE_RANGES[z].start&&i<=ZONE_RANGES[z].end){zone=z;break}tiles.push({type:'prop',zone:zone,owner:null,level:1})}}return tiles}
function tileRowCol(i){if(i<=7)return{row:1,col:i+1};if(i<=14)return{row:i-6,col:8};if(i<=21)return{row:8,col:22-i};return{row:29-i,col:1}}
var MARKET_EVENTS=[{type:'boom',name:'BÙNG NỔ CRYPTO',desc:'Thuế +50% / 3 lượt!'},{type:'crash',name:'SỤP ĐỔ',desc:'Nhà giảm 1 cấp!'},{type:'heist',name:'ĐÁNH CẮP',desc:'Người giàu mất 10%!'},{type:'hack',name:'HACK',desc:'Tất cả +$20k!'}];
function triggerMarketEvent(){var ev=MARKET_EVENTS[rnd(MARKET_EVENTS.length)];state.game.global_event={type:ev.type,turnsLeft:3};var ticker=$('marketTicker'),text=$('marketTickerText');ticker.classList.add('active');text.textContent='⚠️ '+ev.name+' — '+ev.desc+' ⚠️';sfx.event();if(ev.type==='crash'){state.game.tiles.forEach(function(t){if(t.type==='prop'&&t.owner&&t.level>1)t.level--})}else if(ev.type==='heist'){var richest=null;state.game.players.forEach(function(p){if(!p.bankrupt&&(!richest||p.money>richest.money))richest=p});if(richest&&richest.money>0){var stolen=Math.floor(richest.money*0.1);richest.money-=stolen;var others=state.game.players.filter(function(p){return!p.bankrupt&&p.username!==richest.username});if(others.length){var share=Math.floor(stolen/others.length);others.forEach(function(p){p.money+=share})}showMoneyFloat(richest.username,-stolen)}}else if(ev.type==='hack'){state.game.players.forEach(function(p){if(!p.bankrupt){p.money+=20000;showMoneyFloat(p.username,20000)}})}setTimeout(function(){ticker.classList.remove('active');text.textContent='📡 '+ev.name+' ('+state.game.global_event.turnsLeft+' LƯỢT) 📡'},5000)}
function renderStaticTiles(){var boardEl=$('board');if(boardEl)boardEl.dataset.board=profile.activeBoard||'neon';var grid=$('boardGrid');grid.innerHTML='';var me=state.game.players.find(function(p){return p.username===myUsername});for(var i=0;i<28;i++){var rc=tileRowCol(i);var tile=state.game.tiles[i];var el=document.createElement('div');el.style.gridRow=rc.row;el.style.gridColumn=rc.col;el.dataset.idx=i;if(tile.type==='start'){el.className='tile corner start';el.innerHTML='<div class="corner-icon">🏁</div><div class="corner-label">XUẤT PHÁT</div>'}else if(tile.type==='jail'){el.className='tile corner jail';el.innerHTML='<div class="corner-icon">🚔</div><div class="corner-label">NHÀ TÙ</div>'}else if(tile.type==='reward'){el.className='tile corner reward';el.innerHTML='<div class="corner-icon">🎁</div><div class="corner-label">THƯỞNG</div>'}else if(tile.type==='teleport'){el.className='tile corner teleport';el.innerHTML='<div class="corner-icon">🌀</div><div class="corner-label">DỊCH CHUYỂN</div>'}else if(tile.type==='prop'){el.className='tile prop';el.style.setProperty('--zone-color',ZONES[tile.zone].color);var owner=tile.owner?state.game.players.find(function(p){return p.username===tile.owner}):null;if(owner){el.classList.add('owned');if(owner.username===myUsername){el.classList.add('my-land');el.style.setProperty('--owner-color',owner.color)}else{el.classList.add('other-land');el.style.setProperty('--owner-color',owner.color)}}var displayPrice=owner?(getBaseValue(i)*tile.level):ZONES[tile.zone].price;var nameShort=ZONES[tile.zone].short;var body='';if(owner){if(owner.username===myUsername)body+='<div class="my-land-badge">⭐</div>';var lv='';for(var l=0;l<tile.level;l++)lv+='<span>🏠</span>';body+='<div class="tile-levels">'+lv+'</div>'}else{body+='<div class="tile-name">'+nameShort+'</div>'}el.innerHTML='<div class="tile-band"><span class="tile-band-text">'+fmtShort(displayPrice)+'</span></div><div class="tile-body">'+body+'</div>'}if(me&&me.pos===i&&!me.bankrupt){el.classList.add('my-position');el.style.setProperty('--my-color',me.color)}grid.appendChild(el)}var center=document.createElement('div');center.className='center-info';var curP=state.game.players.find(function(p){return p.username===state.game.current_turn});var eventHtml='';if(state.game.global_event){var ev=MARKET_EVENTS.find(function(e){return e.type===state.game.global_event.type});if(ev)eventHtml='<div class="event-banner">⚠️ '+ev.name+' ('+state.game.global_event.turnsLeft+')</div>'}center.innerHTML='<div class="center-actions"><button class="icon-btn-sm" data-action="sound">'+(sfxOn?'🔊':'🔇')+'</button><button class="icon-btn-sm" data-action="debug">🐞</button><button class="icon-btn-sm" data-action="quit">✕</button></div>'+eventHtml+'<div class="center-player">'+(curP?'<img class="center-avatar" src="'+curP.avatar+'" style="box-shadow:0 0 15px '+curP.color+';border:2px solid '+curP.color+'"><div class="center-name" style="color:'+curP.color+'">'+esc(curP.name)+'</div>':'')+'</div><div class="center-dice-box"><div class="dice-item" id="centerDice1">🎲</div><div class="dice-item" id="centerDice2">🎲</div></div><button class="center-roll-btn" id="rollBtn">TUNG XÚC XẮC</button><div class="center-status" id="rollInfo">...</div>';grid.appendChild(center);$('rollBtn').onclick=function(){executeRoll()};syncRollBtn()}
function renderCenter(){var old=$('boardGrid').querySelector('.center-info');if(old){var curP=state.game.players.find(function(p){return p.username===state.game.current_turn});var playerEl=old.querySelector('.center-player');if(playerEl&&curP)playerEl.innerHTML='<img class="center-avatar" src="'+curP.avatar+'" style="box-shadow:0 0 15px '+curP.color+';border:2px solid '+curP.color+'"><div class="center-name" style="color:'+curP.color+'">'+esc(curP.name)+'</div>'}}
function renderPawns(){var grid=$('boardGrid');grid.querySelectorAll('.tile-players').forEach(function(c){c.remove()});var posMap={};state.game.players.forEach(function(p){if(p.bankrupt)return;if(!posMap[p.pos])posMap[p.pos]=[];posMap[p.pos].push(p)});Object.keys(posMap).forEach(function(pos){var tileEl=grid.querySelector('[data-idx="'+pos+'"]');if(!tileEl)return;var container=document.createElement('div');container.className='tile-players';posMap[pos].forEach(function(p){var box=document.createElement('div');box.className='pawn-box';box.dataset.user=p.username;var moneyStr=p.money>=1000?'$'+(p.money/1000).toFixed(0)+'k':'$'+p.money;box.innerHTML='<img src="'+p.avatar+'" style="--avatar-color:'+p.color+'"><span class="pawn-money">'+moneyStr+'</span>';container.appendChild(box)});tileEl.appendChild(container)})}
function renderAll(){if(!state.game)return;renderStaticTiles();renderPawns();requestAnimationFrame(fitBoard)}
function syncRollBtn(){var btn=$('rollBtn'),info=$('rollInfo');if(!btn||!info)return;if(!state.game||state.game.winner){btn.disabled=true;info.textContent='Đã kết thúc';return}var curP=state.game.players.find(function(p){return p.username===state.game.current_turn});if(!curP){btn.disabled=true;return}var isMe=curP.username===myUsername,isBot=curP.bot;var hasPending=state.game.pending_action&&state.game.pending_action.player===myUsername;btn.disabled=!isMe||isBot||state.busy||hasPending||state.animating;if(isBot)info.textContent='🤖 '+curP.name+' ĐANG CHƠI...';else if(hasPending)info.textContent='⏳ CHỜ QUYẾT ĐỊNH...';else if(isMe)info.textContent=state.game.is_double?'🎲 XÚC XẮC ĐÔI!':'👉 NHẤN ĐỂ TUNG!';else info.textContent='⏳ ĐANG CHỜ...'}
function getPlayer(username){return state.game.players.find(function(p){return p.username===username})}
function currentPlayer(){return getPlayer(state.game.current_turn)}
async function executeRoll(){if(!state.game||state.game.winner||state.animating)return;var player=currentPlayer();if(!player)return;if(player.username!==myUsername&&!player.bot)return;state.animating=true;state.game.is_double=false;syncRollBtn();try{if(player.jail_turns>0){player.jail_turns--;renderCenter();await sleep(700);advanceTurn();return}var dice1=rollDiceForPlayer(player);var dice2=rollDiceForPlayer(player);var isDouble=(dice1===dice2);var steps=dice1+dice2;var flags=(state.game.player_flags=state.game.player_flags||{});var pFlags=(flags[player.username]=flags[player.username]||{});if(player.username===myUsername&&hasSkill('g_dice')&&!pFlags.dice_bonus_used){steps+=1;pFlags.dice_bonus_used=true;toast('✨ +1 bước!')}var centerDice1=$('centerDice1'),centerDice2=$('centerDice2');if(centerDice1&&centerDice2){centerDice1.classList.add('rolling');centerDice2.classList.add('rolling');sfx.roll();var swap=setInterval(function(){centerDice1.textContent=DICE_FACES[rnd(6)];centerDice2.textContent=DICE_FACES[rnd(6)]},55);await sleep(750);clearInterval(swap);centerDice1.classList.remove('rolling');centerDice2.classList.remove('rolling');centerDice1.textContent=DICE_FACES[dice1-1];centerDice2.textContent=DICE_FACES[dice2-1]}var oldPos=player.pos;var passed=(oldPos+steps)>=28;if(state.playMode!=='online')await animateStepMove(player,steps);else{player.pos=(oldPos+steps)%28;renderPawns()}sfx.land();if(passed){var startBonus=10000;if(player.username===myUsername&&state.game.activeBooster==='stock'){startBonus=Math.floor(startBonus*1.2);if(state.game.boosterTriggered)state.game.boosterTriggered.stock=true}player.money+=startBonus;showMoneyFloat(player.username,startBonus)}renderStaticTiles();renderPawns();renderCenter();await sleep(280);if(isDouble){state.game.doubleStreak=(state.game.doubleStreak||0)+1;if(player.username===myUsername&&hasSkill('g_time')&&state.game.doubleStreak>=2){toast('⏳ Lượt thứ 3!');state.game.is_double=true;state.game.doubleStreak=0}else{toast('🎲 XÚC XẮC ĐÔI!');state.game.is_double=true}}else{state.game.doubleStreak=0}await resolveTile(player,player.pos)}finally{state.animating=false;syncRollBtn()}}
async function animateStepMove(player,steps){var grid=$('boardGrid');var myPawnBox=grid.querySelector('.pawn-box[data-user="'+player.username+'"]');var me=state.game.players.find(function(p){return p.username===myUsername});for(var s=0;s<steps;s++){if(me&&player.username===myUsername){var oldTile=grid.querySelector('[data-idx="'+player.pos+'"]');if(oldTile)oldTile.classList.remove('my-position')}player.pos=(player.pos+1)%28;if(me&&player.username===myUsername){var newTile=grid.querySelector('[data-idx="'+player.pos+'"]');if(newTile){newTile.classList.add('my-position');newTile.style.setProperty('--my-color',me.color)}}if(myPawnBox){var t=grid.querySelector('[data-idx="'+player.pos+'"]');if(t){var c=t.querySelector('.tile-players');if(!c){c=document.createElement('div');c.className='tile-players';t.appendChild(c)}c.appendChild(myPawnBox);myPawnBox.querySelector('img').classList.remove('hopping');void myPawnBox.offsetWidth;myPawnBox.querySelector('img').classList.add('hopping')}}sfx.step();await sleep(170)}if(myPawnBox)myPawnBox.querySelector('img').classList.remove('hopping')}
async function resolveTile(player,tileIdx){var tile=state.game.tiles[tileIdx];if(tile.type==='start'){if(tileIdx===0){player.money+=5000;showMoneyFloat(player.username,5000);sfx.buy()}await commitAndRender();advanceTurn();return}if(tile.type==='jail'){if(player.username===myUsername&&state.game.activeBooster==='charm'&&!state.game.boosterTriggered.charm){state.game.boosterTriggered.charm=true;toast('🍀 Tránh Nhà Tù!');await commitAndRender();advanceTurn();return}player.jail_turns=2;state.game.is_double=false;sfx.lose();await commitAndRender();await sleep(500);advanceTurn();return}if(tile.type==='reward'){var props=[];for(var i=1;i<28;i++)if(state.game.tiles[i].type==='prop')props.push(i);var targetIdx=props[rnd(props.length)];var target=state.game.tiles[targetIdx];if(!target.owner){target.owner=player.username;target.level=1;sfx.buy()}else if(target.owner!==player.username){target.owner=player.username;sfx.buy()}else{player.money+=5000;showMoneyFloat(player.username,5000)}await commitAndRender();await sleep(600);advanceTurn();return}if(tile.type==='teleport'){var props=[];for(var i=1;i<28;i++)if(state.game.tiles[i].type==='prop')props.push(i);player.pos=props[rnd(props.length)];await commitAndRender();await sleep(600);await resolveTile(player,player.pos);return}if(tile.type==='prop'){await resolveProperty(player,tileIdx);return}advanceTurn()}
async function resolveProperty(player,tileIdx){var tile=state.game.tiles[tileIdx];var zone=ZONES[tile.zone];if(!tile.owner){var price=zone.price;if(player.username===myUsername&&hasSkill('m_buy'))price=Math.floor(price*0.9);if(player.bot){if(player.money>=price+30000){player.money-=price;tile.owner=player.username;tile.level=1;showMoneyFloat(player.username,-price);sfx.buy();await commitAndRender();await sleep(500)}advanceTurn()}else if(player.username===myUsername){state.game.pending_action={type:'buy_empty',player:player.username,tileIdx:tileIdx,price:price};await commitAndRender();showBuyEmptyModal(player,tileIdx,price)}else syncRollBtn();return}if(tile.owner===player.username){if(player.bot){var upCost=ZONES[tile.zone].price;if(player.money>=upCost+30000&&tile.level<5){player.money-=upCost;tile.level++;showMoneyFloat(player.username,-upCost);sfx.buy();await commitAndRender();await sleep(500)}advanceTurn()}else if(player.username===myUsername){if(tile.level<5){var upCost=ZONES[tile.zone].price;if(hasSkill('m_up'))upCost=Math.floor(upCost*0.75);state.game.pending_action={type:'upgrade',player:player.username,tileIdx:tileIdx,cost:upCost};await commitAndRender();showUpgradeModal(player,tileIdx,upCost,tile.level)}else{await commitAndRender();await sleep(300);advanceTurn()}}else syncRollBtn();return}var currentBase=getBaseValue(tileIdx);var totalValue=currentBase*tile.level;var buyBackPrice=Math.floor(totalValue*1.5);var rentPrice=Math.floor(totalValue*0.5);if(state.game.global_event&&state.game.global_event.type==='boom')rentPrice=Math.floor(rentPrice*1.5);if(player.username===myUsername&&hasSkill('w_buyback'))buyBackPrice=Math.floor(buyBackPrice*0.85);var owner=getPlayer(tile.owner);if(owner&&owner.username===myUsername){if(hasSkill('w_rent'))rentPrice=Math.floor(rentPrice*1.2);if(hasSkill('w_empire')){var propCount=state.game.tiles.filter(function(t){return t.type==='prop'&&t.owner===myUsername}).length;rentPrice=Math.floor(rentPrice*(1+(propCount-1)*0.03))}if(hasSkill('m_chain')&&getChainCount(tileIdx)>=3)rentPrice=Math.floor(rentPrice*1.5)}if(player.username===myUsername&&state.game.activeBooster==='shield'&&!state.game.boosterTriggered.shield){state.game.boosterTriggered.shield=true;toast('🛡️ Miễn thuế!');await commitAndRender();await sleep(400);advanceTurn();return}if(player.bot){if(player.money>=rentPrice){player.money-=rentPrice;if(owner)owner.money+=rentPrice;if(owner&&owner.username===myUsername)questAdd('rent',1);showMoneyFloat(player.username,-rentPrice);if(owner)showMoneyFloat(owner.username,rentPrice);sfx.pay();await commitAndRender();await sleep(500);advanceTurn();return}if(player.money>=buyBackPrice){player.money-=buyBackPrice;if(owner)owner.money+=buyBackPrice;tile.owner=player.username;showMoneyFloat(player.username,-buyBackPrice);sfx.buy();await commitAndRender();await sleep(500);advanceTurn();return}doBankrupt(player,owner,buyBackPrice);await commitAndRender();await sleep(700);advanceTurn();return}if(player.username===myUsername){state.game.pending_action={type:'opponent_tile',player:player.username,tileIdx:tileIdx,chainValue:buyBackPrice,rentPrice:rentPrice,chainCount:getChainCount(tileIdx)};await commitAndRender();showOpponentModal(player,tileIdx,buyBackPrice,rentPrice,getChainCount(tileIdx))}else syncRollBtn()}
function doBankrupt(player,creditor,amount){var flags=(state.game.player_flags=state.game.player_flags||{});var pFlags=(flags[player.username]=flags[player.username]||{});if(player.username===myUsername&&hasSkill('g_revive')&&!pFlags.revive_used){pFlags.revive_used=true;player.money=50000;toast('🔮 Hồi sinh $50k!');sfx.win();return}player.bankrupt=true;player.money=0;state.game.tiles.forEach(function(t){if(t.type==='prop'&&t.owner===player.username){if(creditor&&!creditor.bankrupt&&creditor.username!==player.username){t.owner=creditor.username}else{t.owner=null;t.level=1}}});sfx.lose();var alive=state.game.players.filter(function(p){return!p.bankrupt});if(alive.length===1){state.game.winner=alive[0].username;state.game.finished_at=Date.now()}}
function advanceTurn(){if(!state.game||state.game.winner){commitAndRender().then(function(){showWinOverlay()});return}if(state.game.is_double){state.game.is_double=false;state.game.turn_count++;if(state.game.turn_count>0&&state.game.turn_count%5===0)triggerMarketEvent();commitAndRender().then(function(){var p=currentPlayer();if(p&&p.bot)setTimeout(function(){executeRoll()},1000)});return}state.game.turn_count=(state.game.turn_count||0)+1;if(state.game.turn_count>0&&state.game.turn_count%5===0)triggerMarketEvent();else if(state.game.global_event){state.game.global_event.turnsLeft--;if(state.game.global_event.turnsLeft<=0){state.game.global_event=null;var text=$('marketTickerText');if(text)text.textContent='📡 THỊ TRƯỜNG ỔN ĐỊNH 📡'}}var idx=state.game.players.findIndex(function(p){return p.username===state.game.current_turn});for(var i=1;i<=state.game.players.length;i++){idx=(idx+1)%state.game.players.length;if(!state.game.players[idx].bankrupt){state.game.current_turn=state.game.players[idx].username;state.game.pending_action=null;state.game.doubleStreak=0;break}}commitAndRender().then(function(){var nextP=currentPlayer();if(nextP)showTurnBanner(nextP.name,nextP.color);if(nextP&&nextP.bot&&!state.game.winner)setTimeout(function(){executeRoll()},1000)})}
async function commitAndRender(){renderAll();if(state.playMode==='online'&&room)await commitOnline()}
async function handleBuyEmpty(yes){var pa=state.game.pending_action;if(!pa||pa.type!=='buy_empty')return;var player=getPlayer(pa.player);if(!player)return;if(yes&&player.money>=pa.price){player.money-=pa.price;state.game.tiles[pa.tileIdx].owner=player.username;state.game.tiles[pa.tileIdx].level=1;showMoneyFloat(player.username,-pa.price);sfx.buy();addXP(10);profile.stats.buys++;questAdd('buy',1)}state.game.pending_action=null;hideActionModal();await commitAndRender();await sleep(400);advanceTurn()}
async function handleUpgrade(yes){var pa=state.game.pending_action;if(!pa||pa.type!=='upgrade')return;var player=getPlayer(pa.player);if(!player)return;if(yes&&player.money>=pa.cost){player.money-=pa.cost;state.game.tiles[pa.tileIdx].level++;showMoneyFloat(player.username,-pa.cost);sfx.buy();addXP(15);profile.stats.upgrades++;questAdd('upgrade',1)}state.game.pending_action=null;hideActionModal();await commitAndRender();await sleep(400);advanceTurn()}
async function handleOpponentAction(action){var pa=state.game.pending_action;if(!pa||pa.type!=='opponent_tile')return;var player=getPlayer(pa.player);if(!player)return;var tile=state.game.tiles[pa.tileIdx];var owner=getPlayer(tile.owner);if(action==='rent'){if(player.money<pa.rentPrice)return toast('Không đủ tiền!');player.money-=pa.rentPrice;if(owner)owner.money+=pa.rentPrice;showMoneyFloat(player.username,-pa.rentPrice);if(owner)showMoneyFloat(owner.username,pa.rentPrice);sfx.pay()}else if(action==='buy'){if(player.money<pa.chainValue)return toast('Không đủ tiền!');player.money-=pa.chainValue;if(owner)owner.money+=pa.chainValue;tile.owner=player.username;showMoneyFloat(player.username,-pa.chainValue);if(owner)showMoneyFloat(owner.username,pa.chainValue);sfx.buy()}else if(action==='bankrupt')doBankrupt(player,owner,pa.chainValue);state.game.pending_action=null;hideActionModal();await commitAndRender();await sleep(400);advanceTurn()}
async function handleEmergencySell(){var pa=state.game.pending_action;if(!pa||pa.type!=='opponent_tile')return;var player=getPlayer(pa.player);if(!player)return;var myProps=[];state.game.tiles.forEach(function(t,idx){if(t.type==='prop'&&t.owner===player.username)myProps.push({idx:idx,value:getBaseValue(idx)*t.level})});if(!myProps.length)return toast('Không có đất để bán!');myProps.sort(function(a,b){return a.value-b.value});var sold=0;for(var i=0;i<myProps.length;i++){if(player.money>=pa.rentPrice)break;var p=myProps[i],sellPrice=Math.floor(p.value*0.5);player.money+=sellPrice;state.game.tiles[p.idx].owner=null;state.game.tiles[p.idx].level=1;sold++;showMoneyFloat(player.username,sellPrice)}if(sold>0)toast('Đã bán '+sold+' mảnh đất!');await commitAndRender();await sleep(400);if(player.money>=pa.rentPrice)handleOpponentAction('rent');else handleOpponentAction('bankrupt')}
function showBuyEmptyModal(player,tileIdx,price){var zone=ZONES[state.game.tiles[tileIdx].zone];var canBuy=player.money>=price;var skillNote=(player.username===myUsername&&hasSkill('m_buy'))?'<div class="row"><span>Ưu đãi Mặc Cả</span><b class="buff">-10%</b></div>':'';$('actionModal').innerHTML='<h2>MUA ĐẤT</h2><div class="sub">'+zone.name+'</div><div class="prop-info"><div class="row"><span>Giá mua</span><b>'+fmtMoney(price)+'</b></div>'+skillNote+'<div class="row"><span>Ví</span><b>'+fmtMoney(player.money)+'</b></div><div class="row"><span>Sau mua</span><b>'+fmtMoney(player.money-price)+'</b></div></div><div class="actions"><button class="btn btn-buy" id="btnBuyYes" '+(canBuy?'':'disabled')+'>💰 MUA</button><button class="btn btn-skip" id="btnBuyNo">BỎ QUA</button></div>';$('actionOverlay').hidden=false;if(canBuy)$('btnBuyYes').onclick=function(){handleBuyEmpty(true)};$('btnBuyNo').onclick=function(){handleBuyEmpty(false)};startDecisionTimeout()}
